const { chromium } = require('playwright');
const path = require('path');

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
  const resolved = path.resolve(
    '<run>/index.html'
  ).split(path.sep).join('/');
  await page.goto('file:///' + resolved);

  await page.keyboard.down('Alt');
  await page.keyboard.press('KeyA');
  await page.keyboard.up('Alt');
  await page.waitForTimeout(200);

  const info = await page.evaluate(() => {
    const w = document.querySelector('.monster-walker');
    const cs = getComputedStyle(w);
    const anims = w.getAnimations();
    return {
      crossingVar: cs.getPropertyValue('--crossing'),
      frameW: cs.getPropertyValue('--frame-w'),
      stride: cs.getPropertyValue('--stride'),
      cycle: cs.getPropertyValue('--cycle'),
      animationDuration: cs.animationDuration,
      animCount: anims.length,
      animDurations: anims.map(a => a.effect && a.effect.getTiming().duration),
      inlineStyle: w.getAttribute('style'),
    };
  });
  console.log(JSON.stringify(info, null, 2));

  await browser.close();
})();
NODEEOF
